#!/usr/bin/env bash
set -euo pipefail
cat > route-planner.html <<'HTML'
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenEval Field Route</title><style>
:root{color-scheme:dark;font-family:ui-sans-serif,system-ui;background:#0d1219;color:#f5f7f2}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#16251e}main{width:min(980px,calc(100vw - 36px));padding:28px;border:1px solid #3b5a48;border-radius:24px;background:#18271f}h1{margin:0}.lede{color:#b7c9bb}.layout{display:grid;grid-template-columns:1.35fr .65fr;gap:18px;margin-top:22px}.map{position:relative;min-height:390px;border-radius:18px;border:1px solid #41624e;background:linear-gradient(135deg,#263f31,#17261e);overflow:hidden}.route{position:absolute;left:14%;right:14%;top:52%;height:5px;background:#e7c86b;transform:rotate(-13deg);box-shadow:0 0 0 4px #e7c86b33}.landmark{position:absolute;display:grid;gap:4px;place-items:center;font-size:11px;color:#f4f7ef}.landmark b{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;border:2px solid #f4f7ef;background:#1a3326}.landmark[data-route-state="current"] b{background:#d7655b}.l1{left:10%;bottom:18%}.l2{left:28%;top:27%}.l3{left:48%;bottom:30%}.l4{left:67%;top:20%}.l5{right:8%;top:52%}.panel{padding:18px;border-radius:16px;background:#213629}.panel h2{margin-top:0}.legend{display:grid;gap:10px;padding:0;list-style:none;color:#c3d4c5;font-size:12px}.legend li::before{content:"•";color:#e7c86b;font-size:20px;vertical-align:-2px;margin-right:8px}.next-action{margin-top:22px;padding:13px;border-left:3px solid #e7c86b;background:#2a4432;color:#eef4ea}@media(max-width:700px){.layout{grid-template-columns:1fr}.map{min-height:320px}}
</style></head><body><main><h1>OpenEval Field Route</h1><p class="lede">A calm route from the observatory to the evidence garden.</p><div class="layout"><section class="map" aria-label="Field route map"><div class="route" aria-label="Route from Start to Finish"></div><div class="landmark l1" data-landmark="start" data-route-state="start"><b>1</b><span>Start</span></div><div class="landmark l2" data-landmark="bridge"><b>2</b><span>Signal bridge</span></div><div class="landmark l3" data-landmark="grove"><b>3</b><span>Memory grove</span></div><div class="landmark l4" data-landmark="tower" data-route-state="current"><b>4</b><span>Current: watchtower</span></div><div class="landmark l5" data-landmark="finish"><b>5</b><span>Finish</span></div></section><aside class="panel"><h2>Route legend</h2><ul class="legend"><li>Numbered circles are ordered stops</li><li>Amber line is the recommended route</li><li>Red circle marks current position</li></ul><div class="next-action" data-route-state="next-action"><strong>Next action</strong><br>Cross the watchtower and continue to the evidence garden.</div></aside></div></main></body></html>
HTML
